{
  "commonPhenomenon": "通道对账显示支付成功，但本地订单状态仍为处理中，存在状态不一致。",
  "facts": [
    {
      "statement": "2026-09-28T10:14:00Z 观察到一笔 CNY 1000 的订单，通道对账记录为支付成功，而本地订单状态仍在处理中。",
      "evidenceIds": [
        "E-014"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧确认为支付成功，与本地系统当前持有的处理中状态存在冲突。",
      "evidenceIds": [
        "E-014"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "平台与通道支付终态冲突：本地系统未及时同步通道的成功状态，或存在旧快照导致的认知偏差。",
      "evidenceIds": [
        "E-014"
      ],
      "verification": "需确认商户订单号、通道交易号和商户号指向同一交易；比较状态采集时间、时区、来源及通道状态映射；查看回调、查单和人工操作审计。获取新的只读查单结果并由人工复核资金流水。"
    },
    {
      "hypothesis": "支付成功回调缺失：通道已发送成功通知，但平台未收到或未处理该回调，导致本地状态未更新。",
      "evidenceIds": [
        "E-014"
      ],
      "verification": "用商户订单号和通道交易号确认是同一笔交易；比对通道支付时间、回调投递记录、平台入口访问日志和商户通知应答。检查日志时间范围、时区与保留期限，区分未投递、网络失败、验签失败或处理失败。"
    },
    {
      "hypothesis": "关单后收到支付成功通知：本地可能误判或提前关单，随后收到了迟到的通道成功通知。",
      "evidenceIds": [
        "E-014"
      ],
      "verification": "按同一订单核对关单请求、通道对关单的应答、通道实际支付时间、通知生成时间和平台接收时间。检查时间戳时区、通道交易号及状态映射，并通过可信只读查单确认当前资金结果。"
    }
  ],
  "checkSteps": [
    "确认商户订单号、通道交易号和商户号是否指向同一笔交易。",
    "比对通道支付时间、回调投递记录、平台入口访问日志和商户通知应答。",
    "检查日志时间范围、时区与保留期限，确认是否存在时间差导致的误解。",
    "通过可信只读查单确认当前资金结果，避免依赖旧快照。",
    "由有权限的人员按业务流程复核后续处理，不自动改写状态。"
  ],
  "missingInformation": [
    "具体的通道交易号（Channel Transaction ID）。",
    "本地订单当前的详细状态码及最后更新时间戳。",
    "通道回调的投递记录及平台接收日志。",
    "是否存在之前的关单或取消操作记录。"
  ],
  "knowledgeCitations": [
    "terminal-conflict",
    "lost-callback",
    "late-success-after-close"
  ],
  "knowledgeOmissionReason": null
}
